import logging


def catch_mtkue_interface_exception(func):  # noqa: C901

    _MTK_ELG_LOG = "mtk.elg"

    def _collect_pyro_server_log(mtkue):
        if not mtkue.is_elg_enabled():
            return
        logging.info("start to collect elg log")

        try:
            mtk_rpc = mtkue.get_mtk_rpc()
            rpc_proxy = mtkue.get_rpc_proxy()
            if not (mtk_rpc or rpc_proxy):
                logging.error("mtk rpc or proxy are invalid, failed to collect elg log")
                return
            elg_log_path = mtk_rpc.workspace.log_dir + _MTK_ELG_LOG
            rpc_proxy.save_elg_log(elg_log_path)

        except Exception as err_info:
            logging.error("failed to collect elg log, {}".format(err_info))

        logging.info("elg log collecting finished ")

    def handle_exception_wrapper(mtkue, *args, **kwargs):
        try:
            func(mtkue, *args, **kwargs)
        except Exception:
            _collect_pyro_server_log(mtkue)
            raise

    return handle_exception_wrapper
